import com.liferay.portal.kernel.dao.orm.PropertyFactoryUtil;
import com.liferay.portal.kernel.dao.orm.RestrictionsFactoryUtil;
import com.liferay.portal.kernel.util.Validator;

import java.util.ArrayList;
import java.util.List;

import org.osgi.service.component.annotations.Component;

import it.servizidigitali.gestionebandi.common.enumeration.OrganizationRoleEnum;
import it.servizidigitali.gestionebandi.common.enumeration.StatoInvioTrasmissioneEnum;
import it.servizidigitali.gestionebandi.model.Trasmissione;
import it.servizidigitali.gestionebandi.service.DomandaBandoLocalServiceUtil;
import it.servizidigitali.gestionebandi.service.TrasmissioneLocalServiceUtil;
import it.servizidigitali.gestionebandi.service.persistence.TrasmissioneFinder;

@Component(service = TrasmissioneFinder.class)
public class TrasmissioneFinderImpl extends TrasmissioneFinderBaseImpl implements TrasmissioneFinder {

	public List<Trasmissione> getTrasmissioniByDomandaBandoIdRuolo(long domandaBandoId, int start, int end, long userId,
			String ruoloStr) {
		OrganizationRoleEnum ruolo = OrganizationRoleEnum.findByName(ruoloStr);
		if (ruolo.isCittadino() || ruolo.isOperatore()) {
			return trasmissionePersistence.findWithDynamicQuery(getQuery(domandaBandoId, userId, ruolo), start, end);
		} else
			return new ArrayList<Trasmissione>();
	}

	public Integer countTrasmissioniByDomandaBandoIdRuolo(long domandaBandoId, long userId,
			String ruoloStr) {
		OrganizationRoleEnum ruolo = OrganizationRoleEnum.findByName(ruoloStr);
		if (ruolo.isCittadino() || ruolo.isOperatore()) {
			return (int) trasmissionePersistence.countWithDynamicQuery(getQuery(domandaBandoId, userId, ruolo));
		} else
			return 0;
	}

	private DynamicQuery getQuery(long domandaBandoId, long userId, OrganizationRoleEnum ruolo) {
		DynamicQuery query = TrasmissioneLocalServiceUtil.dynamicQuery();
		query.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
		if (ruolo.isOperatore()) {
			query.add(RestrictionsFactoryUtil.eq("stato", StatoInvioTrasmissioneEnum.INVIATA.name()));
		}
		if (ruolo.isCittadino()) {
			DynamicQuery domandaBandoDynamicQuery = DomandaBandoLocalServiceUtil.dynamicQuery();
			domandaBandoDynamicQuery.add(RestrictionsFactoryUtil.eq("userId", userId));
			domandaBandoDynamicQuery.setProjection(PropertyFactoryUtil.forName("domandaBandoId"));
			query.add(PropertyFactoryUtil.forName("domandaBandoId").in(domandaBandoDynamicQuery));
		}
		return query;
	}

	public Trasmissione getTrasmissionePiuRecente(long domandaBandoId) {
	    DynamicQuery query = TrasmissioneLocalServiceUtil.dynamicQuery();

	    query.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
	    query.add(RestrictionsFactoryUtil.eq("stato", StatoInvioTrasmissioneEnum.INVIATA.name()));
	    query.addOrder(OrderFactoryUtil.desc("dataInvio"));

	    query.setLimit(0, 1);

	    List<Trasmissione> results = trasmissionePersistence.findWithDynamicQuery(query);

	    if (Validator.isNotNull(results)) return results.get(0);
	    		else return null;
	}

}

