import java.util.List;
import java.util.Set;

import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import it.servizidigitali.scrivaniaoperatore.model.Richiesta;
import it.servizidigitali.scrivaniaoperatore.model.RichiestaFilters;
import it.servizidigitali.scrivaniaoperatore.service.persistence.RichiestaFinder;

/**
 * @author filierim
 * @author rizzitellim
 *
 */

@Component(service = RichiestaFinder.class)
public class RichiestaFinderImpl extends RichiestaFinderBaseImpl implements RichiestaFinder {

	@Reference
	private UserLocalService userLocalService;

	@Override
	public List<Richiesta> findByFilters(RichiestaFilters filters, int start, int end) {

		DynamicQuery dynamicQuery = getDynamicQuery(filters);

		boolean direzione = true;

		String orderByType = filters.getOrderByType();
		if ("desc".equalsIgnoreCase(orderByType)) {
			direzione = false;
		}

		String orderByCol = filters.getOrderByCol();
		if (Validator.isNull(orderByCol)) {
			orderByCol = "richiestaId";
		}

		OrderByComparator<Richiesta> comparator = OrderByComparatorFactoryUtil.create("Richiesta", orderByCol, direzione);
		return richiestaPersistence.findWithDynamicQuery(dynamicQuery, start, end, comparator);

	}

	/**
	 * @param filters
	 * @return
	 */
	private DynamicQuery getDynamicQuery(RichiestaFilters filters) {
		ClassLoader classLoader = getClass().getClassLoader();

		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(Richiesta.class, classLoader);

		if (filters != null) {
			long companyId = filters.getCompanyId();
			List<Long> groupIds = filters.getGroupId();

			if(companyId > 0) {
				dynamicQuery.add(RestrictionsFactoryUtil.eq("companyId", companyId));
			}

			if(ListUtil.isNotNull(groupIds) && ListUtil.isNotEmpty(groupIds)) {
				dynamicQuery.add(RestrictionsFactoryUtil.in("groupId", groupIds));
			}

			if (filters.getIdRichiesta() != null) {
				long filterId;
				try {
					filterId = Long.parseLong(filters.getIdRichiesta());
				}
				catch (NumberFormatException e) {
					filterId = 0;
				}
				dynamicQuery.add(RestrictionsFactoryUtil.eq("richiestaId", filterId));
			}

			if (filters.getNumeroProtocollo() != null) {
				dynamicQuery.add(RestrictionsFactoryUtil.ilike("numeroProtocolloEsteso", "%" + filters.getNumeroProtocollo() + "%"));
			}

			if (filters.getDataDa() != null) {
				dynamicQuery.add(RestrictionsFactoryUtil.ge("dataInvio", filters.getDataDa()));
			}

			if (filters.getDataA() != null) {
				dynamicQuery.add(RestrictionsFactoryUtil.le("dataInvio", filters.getDataA()));
			}

			if (filters.getAutenticazione() != null) {
				dynamicQuery.add(RestrictionsFactoryUtil.eq("invioGuest", !filters.getAutenticazione()));
			}

			if (filters.getTipo() != null) {
				dynamicQuery.add(RestrictionsFactoryUtil.eq("stato", filters.getTipo()));
			}

			if (filters.isEscludiBozze()) {
				dynamicQuery.add(RestrictionsFactoryUtil.ne("stato", "BOZZA"));
			}

			if (filters.getProcessInstanceIds() != null) {
				dynamicQuery.add(RestrictionsFactoryUtil.in("processInstanceId", filters.getProcessInstanceIds()));
			}

			if (filters.getProcedureIds() != null) {
				dynamicQuery.add(RestrictionsFactoryUtil.in("proceduraId", filters.getProcedureIds()));
			}

			if (Validator.isNotNull(filters.getOggettoNote())) {
				String pattern = "%" + filters.getOggettoNote() + "%";
				Disjunction disjunctionQuery = RestrictionsFactoryUtil.disjunction();
				disjunctionQuery.add(RestrictionsFactoryUtil.ilike("oggetto", pattern));
				disjunctionQuery.add(RestrictionsFactoryUtil.ilike("note", pattern));
				dynamicQuery.add(disjunctionQuery);
			}

			if (filters.getNomeCognome() != null) {
				String pattern = "%" + filters.getNomeCognome() + "%";
				dynamicQuery.add(RestrictionsFactoryUtil.ilike("denominazioneRichiedente", pattern));
			}

			if (filters.getCodiceFiscale() != null) {
				dynamicQuery.add(RestrictionsFactoryUtil.ilike("codiceFiscale", "%" + filters.getCodiceFiscale() + "%"));
			}

			if (filters.getServiziIds() != null) {
				dynamicQuery.add(RestrictionsFactoryUtil.in("servizioId", filters.getServiziIds()));
			}

			if (Validator.isNotNull(filters.getPartitaIva())) {
				dynamicQuery.add(RestrictionsFactoryUtil.ilike(
						"partitaIva",
						filters.getPartitaIva().trim() + StringPool.PERCENT
				));
			}
		}
		return dynamicQuery;
	}

	@Override
	public int countByFilters(RichiestaFilters filters) {

		DynamicQuery dynamicQuery = getDynamicQuery(filters);

		return (int) richiestaPersistence.countWithDynamicQuery(dynamicQuery);
	}

	/**
	 * @param cf codiceFiscale utente
	 * @param groupId groupId organizzazione
	 * @return
	 */
	@Override
	public List<Richiesta> findRichiestaByCfAndGroupId(String cf, long groupId, int cur, int delta, String orderByCol, String orderByType) {
		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(Richiesta.class, getClassLoader());

		if (Validator.isNotNull(cf)) {
			dynamicQuery.add(RestrictionsFactoryUtil.eq("codiceFiscale", cf));
		}

		if (groupId > 0) {
			dynamicQuery.add(RestrictionsFactoryUtil.eq("groupId", groupId));
		}

		if (Validator.isNull(orderByCol)) {
			orderByCol = "modifiedDate";
		}

		boolean direzione = "desc".equals(orderByType) ? false : true;

		OrderByComparator<Richiesta> comparator = OrderByComparatorFactoryUtil.create(Richiesta.class.getSimpleName(), orderByCol, direzione);

		int start = QueryUtil.ALL_POS;
		int end = QueryUtil.ALL_POS;
		int[] startEnd = SearchPaginationUtil.calculateStartAndEnd(cur, delta);

		if ((startEnd[0] >= 1) && (startEnd[1] >= 1)) {
			start = startEnd[0];
			end = startEnd[1];
		}

		return richiestaPersistence.findWithDynamicQuery(dynamicQuery, start, end, comparator);
	}

	@Override
	public List<Richiesta> findRichiestaByCodiceFiscaleStatoProceduraId(String codiceFiscale, String stato, long proceduraId) {

		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(Richiesta.class, getClassLoader());

		if (Validator.isNotNull(codiceFiscale)) {
			dynamicQuery.add(RestrictionsFactoryUtil.eq("codiceFiscale", codiceFiscale));
		}

		if (Validator.isNotNull(stato)) {
			dynamicQuery.add(RestrictionsFactoryUtil.eq("stato", stato));
		}

		if (proceduraId > 0) {
			dynamicQuery.add(RestrictionsFactoryUtil.eq("proceduraId", proceduraId));
		}

		dynamicQuery.addOrder(OrderFactoryUtil.desc("modifiedDate"));

		return richiestaPersistence.findWithDynamicQuery(dynamicQuery);

	}

	@Override
	public List<Richiesta> findRichiestaByProcessInstanceIds(Set<String> processInstanceIds, String orderByCol, String orderByType) {

		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(Richiesta.class, getClassLoader());

		if (processInstanceIds != null && processInstanceIds.size()>0) {
			dynamicQuery.add(RestrictionsFactoryUtil.in("processInstanceId", processInstanceIds));
		}

		boolean direzione = true;

		if ("desc".equalsIgnoreCase(orderByType)) {
			direzione = false;
		}

		if (Validator.isNull(orderByCol)) {
			orderByCol = "richiestaId";
		}

		OrderByComparator<Richiesta> comparator = OrderByComparatorFactoryUtil.create("Richiesta", orderByCol, direzione);
		return richiestaPersistence.findWithDynamicQuery(dynamicQuery, QueryUtil.ALL_POS, QueryUtil.ALL_POS, comparator);

	}

	@Override
	public List<Long> findRichiesteByConcorso(long concorsoId) {

		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(Richiesta.class, getClassLoader());

		if (Validator.isNotNull(concorsoId)) {
			dynamicQuery.add(RestrictionsFactoryUtil.eq("concorsoId", concorsoId));
		}else{
			dynamicQuery.add(RestrictionsFactoryUtil.gt("concorsoId", 0L));
		}

		dynamicQuery.setProjection(PropertyFactoryUtil.forName("richiestaId"));

		return richiestaPersistence.findWithDynamicQuery(dynamicQuery);

	}

	@Override
	public List<Long> findRichiesteByDonazione(long causaleDonazioneId, String partitaIva) {

		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(Richiesta.class, getClassLoader());

		if (Validator.isNotNull(causaleDonazioneId)) {
			dynamicQuery.add(RestrictionsFactoryUtil.eq("causaleDonazioneId", causaleDonazioneId));
		}else{
			dynamicQuery.add(RestrictionsFactoryUtil.gt("causaleDonazioneId", 0L));
		}

        if(Validator.isNotNull(partitaIva)){
            dynamicQuery.add(RestrictionsFactoryUtil.eq("partitaIva", partitaIva));
        }

		dynamicQuery.setProjection(PropertyFactoryUtil.forName("richiestaId"));

		return richiestaPersistence.findWithDynamicQuery(dynamicQuery);

	}

	@Override
	public List<Richiesta> findRichiesteByStatoAndRichiesteId(String stato, List<Long> richiesteId, int cur, int delta, String orderByCol, String orderByType) {
		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(Richiesta.class, getClassLoader());
		if (Validator.isNotNull(stato)) {
			dynamicQuery.add(RestrictionsFactoryUtil.eq("stato", stato));
		}
		if (Validator.isNotNull(richiesteId)) {
			dynamicQuery.add(RestrictionsFactoryUtil.in("richiestaId", richiesteId));
		}
		if (Validator.isNull(orderByCol)) {
			orderByCol = "modifiedDate";
		}
		boolean direzione = "desc".equals(orderByType) ? false : true;
		OrderByComparator<Richiesta> comparator = OrderByComparatorFactoryUtil.create(Richiesta.class.getSimpleName(), orderByCol, direzione);
		int start = QueryUtil.ALL_POS;
		int end = QueryUtil.ALL_POS;
		int[] startEnd = SearchPaginationUtil.calculateStartAndEnd(cur, delta);
		if ((startEnd[0] >= 1) && (startEnd[1] >= 1)) {
			start = startEnd[0];
			end = startEnd[1];
		}
		return richiestaPersistence.findWithDynamicQuery(dynamicQuery, start, end, comparator);
	}
	@Override
	public Long countRichiesteByStatoAndRichiesteId(String stato, List<Long> richiesteId) {
		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(
				Richiesta.class, getClassLoader()
		);
		if (Validator.isNotNull(stato)) {
			dynamicQuery.add(RestrictionsFactoryUtil.eq("stato", stato));
		}
		if (Validator.isNotNull(richiesteId) && !richiesteId.isEmpty()) {
			dynamicQuery.add(RestrictionsFactoryUtil.in("richiestaId", richiesteId));
		}
		return richiestaPersistence.countWithDynamicQuery(dynamicQuery);
	}

	@Override
	public long countIstanzePresenti(long servizioId, String partitaIva) {
		if (servizioId <= 0) {
			throw new IllegalArgumentException("servizioId must be greater than 0");
		}
		if (Validator.isBlank(partitaIva)) {
			throw new IllegalArgumentException("partitaIva must not be blank");
		}

		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(Richiesta.class, getClassLoader());
		dynamicQuery.add(RestrictionsFactoryUtil.eq("servizioId", servizioId));
		dynamicQuery.add(RestrictionsFactoryUtil.ilike("partitaIva", partitaIva.trim()));

		return richiestaPersistence.countWithDynamicQuery(dynamicQuery);
