import com.liferay.portal.kernel.dao.orm.RestrictionsFactoryUtil;
import com.liferay.portal.kernel.util.ListUtil;
import com.liferay.portal.kernel.util.Validator;
import it.servizidigitali.gestione.referente.istanze.model.RichiestaReferenteIstanza;
import it.servizidigitali.gestione.referente.istanze.model.Filters;
import it.servizidigitali.gestione.referente.istanze.service.persistence.RichiestaReferenteIstanzaFinder;
import org.osgi.service.component.annotations.Component;

import java.util.List;

@Component(service = RichiestaReferenteIstanzaFinder.class)
public class RichiestaReferenteIstanzaFinderImpl extends RichiestaReferenteIstanzaFinderBaseImpl implements RichiestaReferenteIstanzaFinder {

    @Override
    public List<RichiestaReferenteIstanza> findByStatoAndProcessInstanceIdNull(String stato) {
        ClassLoader classLoader = getClass().getClassLoader();

        DynamicQuery query = DynamicQueryFactoryUtil.forClass(RichiestaReferenteIstanza.class, classLoader);
        query.add(RestrictionsFactoryUtil.eq("stato", stato));
        query.add(RestrictionsFactoryUtil.isNull("processInstanceId"));
        return richiestaReferenteIstanzaPersistence.findWithDynamicQuery(query);
    }

    @Override
    public List<RichiestaReferenteIstanza> searchRichiestaReferente(Filters filter) {
        DynamicQuery query = createSearchQuery(filter);

        return richiestaReferenteIstanzaPersistence.findWithDynamicQuery(query);
    }

    @Override
    public long countRichiestaReferente(Filters filter) {
        DynamicQuery query = createSearchQuery(filter);

        return richiestaReferenteIstanzaPersistence.countWithDynamicQuery(query);
    }

    private DynamicQuery createSearchQuery(Filters filter) {
        ClassLoader classLoader = getClass().getClassLoader();

        DynamicQuery query = DynamicQueryFactoryUtil.forClass(RichiestaReferenteIstanza.class, classLoader);
        if (Validator.isNotNull(filter.getUserId())) {
            query.add(RestrictionsFactoryUtil.eq("userId", filter.getUserId()));
        }
        if (Validator.isNotNull(filter.getDominio())) {
            query.add(RestrictionsFactoryUtil.eq("dominio", filter.getDominio()));
        }
        if (Validator.isNotNull(filter.getCodiceFiscale())) {
            query.add(RestrictionsFactoryUtil.eq("codiceFiscale", filter.getCodiceFiscale()));
        }
        if (Validator.isNotNull(filter.getServizioId())) {
            query.add(RestrictionsFactoryUtil.eq("servizioId", filter.getServizioId()));
        }
        if (Validator.isNotNull(filter.getStato())) {
            query.add(RestrictionsFactoryUtil.eq("stato", filter.getStato()));
        }
        if (ListUtil.isNotNull(filter.getStatiEsclusi()) && ListUtil.isNotEmpty(filter.getStatiEsclusi())) {
            query.add(RestrictionsFactoryUtil.not(PropertyFactoryUtil.forName("stato").in(filter.getStatiEsclusi())));
        }
        if (Validator.isNotNull(filter.getRichiestaReferenteIstanzaId())) {
            query.add(RestrictionsFactoryUtil.eq("richiestaReferenteIstanzaId", filter.getRichiestaReferenteIstanzaId()));
        }
        if (Validator.isNotNull(filter.getRichiestaId())) {
            query.add(RestrictionsFactoryUtil.eq("richiestaId", filter.getRichiestaId()));
        }
        if (Validator.isNotNull(filter.getProcedimentoId())) {
            query.add(RestrictionsFactoryUtil.eq("procedimentoId", filter.getProcedimentoId()));
        }
        if (Validator.isNotNull(filter.getPartitaIva())) {
            query.add(RestrictionsFactoryUtil.eq("partitaIva", filter.getPartitaIva()));
        }
        if (Validator.isNotNull(filter.getDataInserimentoDa())) {
            query.add(RestrictionsFactoryUtil.ge("createDate", filter.getDataInserimentoDa()));
        }
        if (Validator.isNotNull(filter.getDataInserimentoA())) {
            query.add(RestrictionsFactoryUtil.le("createDate", filter.getDataInserimentoA()));
        }

        if (ListUtil.isNotNull(filter.getProcessInstanceIds()) && ListUtil.isNotEmpty(filter.getProcessInstanceIds())) {
            query.add(PropertyFactoryUtil.forName("processInstanceId").in(filter.getProcessInstanceIds()));
        }
        return query;
    }
}

