38		private DynamicQuery getQuery(long bandoId, String ragioneSociale, String insegna, String cap, String stato) {
39			ClassLoader classLoader = getClass().getClassLoader();
40			DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(AttivitaStorica.class, classLoader);
41	
42			// MODIFICA: Gestione doppio caso (domandaBandoId associato a bandoId OPPURE domandaBandoId = 0)
43			if (bandoId > 0) {
44				DynamicQuery domandaBandoDynamicQuery = DomandaBandoLocalServiceUtil.dynamicQuery();
45				domandaBandoDynamicQuery.add(RestrictionsFactoryUtil.eq("bandoId", bandoId));
46				domandaBandoDynamicQuery.setProjection(PropertyFactoryUtil.forName("domandaBandoId"));
47	
48				// Crea OR: (domandaBandoId IN (subquery) OR domandaBandoId = 0)
49				Disjunction disjunction = RestrictionsFactoryUtil.disjunction();
50				disjunction.add(PropertyFactoryUtil.forName("domandaBandoId").in(domandaBandoDynamicQuery));
51				disjunction.add(RestrictionsFactoryUtil.eq("domandaBandoId", 0L));
52	
53				dynamicQuery.add(disjunction);
54			}
55	
56			if (Validator.isNotNull(ragioneSociale)) {
57				dynamicQuery.add(RestrictionsFactoryUtil.like("ragioneSociale",
58						StringPool.PERCENT + ragioneSociale + StringPool.PERCENT));
59			}
60	
61			if (Validator.isNotNull(insegna)) {
62				dynamicQuery.add(RestrictionsFactoryUtil.like("insegna",
63						StringPool.PERCENT + insegna + StringPool.PERCENT));
64			}
65	
66			if (Validator.isNotNull(cap)) {
67				dynamicQuery.add(RestrictionsFactoryUtil.like("cap",
68						StringPool.PERCENT + cap + StringPool.PERCENT));
69			}
70	
71			if (Validator.isNotNull(stato)) {
72				dynamicQuery.add(RestrictionsFactoryUtil.eq("stato", stato));
73			}
74	
75			return dynamicQuery;
76		}
