	public long countByFilters(long bandoId, String ragioneSociale, String insegna, String cap, String stato) {
		return attivitaStoricaPersistence.countWithDynamicQuery(
				getQuery(bandoId, ragioneSociale, insegna, cap, stato));
	}

	private DynamicQuery getQuery(long bandoId, String ragioneSociale, String insegna, String cap, String stato) {
		ClassLoader classLoader = getClass().getClassLoader();
		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(AttivitaStorica.class, classLoader);

		// MODIFICA: Gestione doppio caso (domandaBandoId associato a bandoId OPPURE domandaBandoId = 0)
		if (bandoId > 0) {
			DynamicQuery domandaBandoDynamicQuery = DomandaBandoLocalServiceUtil.dynamicQuery();
			domandaBandoDynamicQuery.add(RestrictionsFactoryUtil.eq("bandoId", bandoId));
			domandaBandoDynamicQuery.setProjection(PropertyFactoryUtil.forName("domandaBandoId"));

			// Crea OR: (domandaBandoId IN (subquery) OR domandaBandoId = 0)
			Disjunction disjunction = RestrictionsFactoryUtil.disjunction();
			disjunction.add(PropertyFactoryUtil.forName("domandaBandoId").in(domandaBandoDynamicQuery));
			disjunction.add(RestrictionsFactoryUtil.eq("domandaBandoId", 0L));

			dynamicQuery.add(disjunction);
		}

		if (Validator.isNotNull(ragioneSociale)) {
			dynamicQuery.add(RestrictionsFactoryUtil.like("ragioneSociale",
					StringPool.PERCENT + ragioneSociale + StringPool.PERCENT));
		}

		if (Validator.isNotNull(insegna)) {
			dynamicQuery.add(RestrictionsFactoryUtil.like("insegna",
					StringPool.PERCENT + insegna + StringPool.PERCENT));
		}

		if (Validator.isNotNull(cap)) {
			dynamicQuery.add(RestrictionsFactoryUtil.like("cap",
					StringPool.PERCENT + cap + StringPool.PERCENT));
		}

		if (Validator.isNotNull(stato)) {
			dynamicQuery.add(RestrictionsFactoryUtil.eq("stato", stato));
		}

		return dynamicQuery;
	}

	public List<AttivitaStorica> getAttivitaDaApprovare(long bandoId) {
		ClassLoader classLoader = getClass().getClassLoader();
		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(AttivitaStorica.class, classLoader);

		// MODIFICA: Gestione doppio caso anche qui
		if (bandoId > 0) {
			DynamicQuery domandaBandoDynamicQuery = DomandaBandoLocalServiceUtil.dynamicQuery();
			domandaBandoDynamicQuery.add(RestrictionsFactoryUtil.eq("bandoId", bandoId));
			domandaBandoDynamicQuery.setProjection(PropertyFactoryUtil.forName("domandaBandoId"));

			// Crea OR: (domandaBandoId IN (subquery) OR domandaBandoId = 0)
			Disjunction disjunction = RestrictionsFactoryUtil.disjunction();
			disjunction.add(PropertyFactoryUtil.forName("domandaBandoId").in(domandaBandoDynamicQuery));
			disjunction.add(RestrictionsFactoryUtil.eq("domandaBandoId", 0L));

			dynamicQuery.add(disjunction);
		}

		dynamicQuery.add(RestrictionsFactoryUtil.isNull("dataRevoca"));
		dynamicQuery.add(RestrictionsFactoryUtil.isNull("attoDirigenziale"));
		dynamicQuery.add(RestrictionsFactoryUtil.eq("stato", StatoAttivitaStoricaEnum.ATTESA_APPROVAZIONE.name()));

		return attivitaStoricaPersistence.findWithDynamicQuery(dynamicQuery);
	}

	@Override
	public long countByAttivitaStoricheByAndCapAndPIvaAndRiconoscimento(String cap, String partitaIva, String riconoscimento) {
		ClassLoader classLoader = getClass().getClassLoader();

		DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(AttivitaStorica.class, classLoader);
		dynamicQuery.add(RestrictionsFactoryUtil.eq("cap", cap));
		dynamicQuery.add(RestrictionsFactoryUtil.eq("partitaIva", partitaIva));
		dynamicQuery.add(RestrictionsFactoryUtil.eq("riconoscimento", riconoscimento));
		return attivitaStoricaPersistence.countWithDynamicQuery(dynamicQuery);
	}
}

