package it.servizidigitali.gestione.referente.istanze.service.persistence.impl;


import com.liferay.portal.kernel.dao.orm.DynamicQuery;
import com.liferay.portal.kernel.dao.orm.DynamicQueryFactoryUtil;
import com.liferay.portal.kernel.dao.orm.PropertyFactoryUtil;
import com.liferay.portal.kernel.dao.orm.RestrictionsFactoryUtil;
import com.liferay.portal.kernel.util.ListUtil;
import com.liferay.portal.kernel.util.Validator;
import it.servizidigitali.gestione.referente.istanze.model.AllegatoReferenteIstanza;
import it.servizidigitali.gestione.referente.istanze.model.Filters;
import it.servizidigitali.gestione.referente.istanze.model.RichiestaReferenteIstanza;
import it.servizidigitali.gestione.referente.istanze.service.persistence.AllegatoReferenteIstanzaFinder;
import it.servizidigitali.gestione.referente.istanze.service.persistence.RichiestaReferenteIstanzaFinder;
import org.osgi.service.component.annotations.Component;

import java.util.List;

@Component(service = AllegatoReferenteIstanzaFinder.class)
public class AllegatoReferenteIstanzaFinderImpl extends AllegatoReferenteIstanzaFinderBaseImpl implements AllegatoReferenteIstanzaFinder {
    public List<AllegatoReferenteIstanza> cercaAllegati(
            long richiestaReferenteIstanzaId, boolean principale, boolean interno, long groupId, long companyId) {

        DynamicQuery dynamicQuery = DynamicQueryFactoryUtil
                .forClass(AllegatoReferenteIstanza.class, getClass().getClassLoader())
                .add(RestrictionsFactoryUtil.eq("richiestaReferenteIstanzaId", richiestaReferenteIstanzaId))
                .add(RestrictionsFactoryUtil.eq("principale", principale))
                .add(RestrictionsFactoryUtil.eq("interno", interno))
                .add(RestrictionsFactoryUtil.eq("groupId", groupId))
                .add(RestrictionsFactoryUtil.eq("companyId", companyId));

        return allegatoReferenteIstanzaPersistence.findWithDynamicQuery(dynamicQuery);
    }

}
